// Extract clean text from HTML
const html = $input.item.json.data || $input.item.json.body || $input.item.json || '';
const htmlStr = typeof html === 'string' ? html : JSON.stringify(html);

// Remove script and style tags
let text = htmlStr
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Limit to first 8000 characters to stay within context limits
text = text.substring(0, 8000);

return {
  json: {
    website_url: $('Install Chatbot Webhook').item.json.website_url,
    business_name: $('Install Chatbot Webhook').item.json.business_name,
    scraped_text: text,
    scraped_at: new Date().toISOString()
  }
};

